add-metadata-to-every-object-property:
%dw 2.0
output application/json
---
payload mapObject (value, key) -> {
  (key): {
    value: value,
    "type": if (value is String) "string" else if (value is Number) "number" else "boolean",
    updatedAt: "2024-01-01"
  }
}

build-a-summary-object-from-array-data:
%dw 2.0
output application/json
---
do {
  var totals = payload reduce (r, acc = {}) -> acc ++ { (r.region): (acc[r.region] default 0) + r.amount }
  var topRegion = ((totals pluck (v, k) -> { region: k, total: v }) orderBy (- $.total))[0].region
  ---
  { totalSales: payload reduce (r, acc = 0) -> acc + r.amount, topRegion: topRegion, salesCount: sizeOf(payload) }
}

build-complex-string-processing-pipeline:
%dw 2.0
output application/json
---
payload.rows map (row) ->
  do {
    var fields = (trim(row) splitBy " | ") map trim($)
    ---
    { name: fields[0], age: fields[1], role: fields[2], email: fields[3] }
  }

build-search-keywords-from-text-fields:
%dw 2.0
output application/json
---
do {
  var words = payload.description splitBy " "
  ---
  { keywords: (((words filter (w) -> sizeOf(w) >= 4) map lower($)) distinctBy $) joinBy "," }
}

