convert-legacy-system-fields-into-modern:
%dw 2.0
import capitalize from dw::core::Strings
output application/json
---
payload mapObject (value, key) ->
  do {
    var parts = (key as String) splitBy "_"
    var withoutPrefix = parts[1 to -1]
    var camelKey = lower(withoutPrefix[0]) ++ ((withoutPrefix[1 to -1] default []) map capitalize($) joinBy "")
    ---
    { (camelKey): value }
  }

convert-product-attributes-into-display-:
%dw 2.0
import capitalize from dw::core::Strings
output application/json
---
payload mapObject (value, key) ->
  do {
    var label = ((key as String replace "_" with " ") splitBy " " map capitalize($)) joinBy " "
    var display = if ((key as String) endsWith "_weight") (value as String { format: "0.0#########" }) ++ " kg"
                  else if ((key as String) endsWith "_price") "\$" ++ (value as String)
                  else value as String
    ---
    { (label): display }
  }

create-nested-transformations-using-mult:
%dw 2.0
output application/json
---
(payload
  filter (dept) -> sizeOf(dept.employees filter (e) -> e.salary > 0) > 1)
  map (dept) -> {
    dept: dept.dept,
    employees: dept.employees map (emp) -> { name: emp.name, salary: emp.salary, band: if (emp.salary >= 70000) "Senior" else "Junior" }
  }

generate-dynamic-object-validation-outpu:
%dw 2.0
output application/json
---
do {
  var req = payload.requiredFields
  var data = payload filterObject ((v, k) -> (k as String) != "requiredFields")
  ---
  {
    valid: data filterObject ((v, k) -> (req contains (k as String)) and v != null and v != ""),
    invalid: (req filter (f) -> (data[f] == null or data[f] == "")) reduce (f, acc = {}) -> acc ++ { (f): "MISSING" }
  }
}

generate-financial-summaries-from-transa:
%dw 2.0
output application/json
---
do {
  var summary = payload reduce (tx, acc = { credits: 0, debits: 0, count: 0 }) ->
    if (tx."type" == "credit")
      { credits: acc.credits + tx.amount, debits: acc.debits, count: acc.count + 1 }
    else
      { credits: acc.credits, debits: acc.debits + tx.amount, count: acc.count + 1 }
  ---
  { totalCredits: summary.credits, totalDebits: summary.debits, netBalance: summary.credits - summary.debits, transactionCount: summary.count }
}

generate-product-labels-with-category-in:
%dw 2.0
output application/json
---
payload map (p) -> {
  label: "[" ++ upper(p.category) ++ "] " ++ p.name ++ " - \$" ++ (p.price as String { format: "0.00" })
}

group-customers-by-membership-type:
%dw 2.0
output application/json
---
(payload groupBy $.membershipType) mapObject (members, mType) -> {
  (mType): { count: sizeOf(members), members: members map $.name }
}

process-multi-level-nested-arrays-using:
%dw 2.0
output application/json
---
flatten(payload pluck (deptObj, deptName) ->
  deptObj.employees map { department: deptName, empIndex: $$ + 1, name: $ }
)

store-erp-mapping-logic-as-function-valu:
%dw 2.0
output application/json
var toSAP = (p) -> { sapId: "SAP-" ++ p.id, sapDesc: upper(p.name), account: "Z001" }
var toOracle = (p) -> { oracleRef: "ORA-" ++ p.id, itemDesc: p.name, glCode: "4000" }
var toNetsuite = (p) -> { nsId: "NS-" ++ p.id, description: p.name, "class": "GENERAL" }
var mapFn = if (payload.targetSystem == "SAP") toSAP else if (payload.targetSystem == "Oracle") toOracle else toNetsuite
---
payload.products map (p) -> mapFn(p)
